// B2BMaintenanceAudioController.ts
// Owns: every sound cue in the Lens (generated by /build-sfx into Assets/GeneratedSFX).
// Expects: nothing wired; WAVs are fixed internal assets loaded via requireAsset.
// Must not: decide when cues play (Main calls these methods on flow events).

const SFX_CLICK = requireAsset("../GeneratedSFX/ButtonClick.wav") as AudioTrackAsset
const SFX_SCAN = requireAsset("../GeneratedSFX/ScanSweep.wav") as AudioTrackAsset
const SFX_FAULT = requireAsset("../GeneratedSFX/FaultAlert.wav") as AudioTrackAsset
const SFX_SNAP = requireAsset("../GeneratedSFX/PsuSnap.wav") as AudioTrackAsset
const SFX_SUCCESS = requireAsset("../GeneratedSFX/StepSuccess.wav") as AudioTrackAsset
const SFX_BOOT = requireAsset("../GeneratedSFX/PowerBoot.wav") as AudioTrackAsset
const SFX_COMPLETE = requireAsset("../GeneratedSFX/MaintenanceComplete.wav") as AudioTrackAsset

@component
export class B2BMaintenanceAudioController extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">B2BMaintenanceAudioController – sound cues</span>')
  @ui.separator
  @ui.group_start("Settings")
  @input
  @hint("Master volume for all sound cues")
  @widget(new SliderWidget(0, 1, 0.05))
  sfxVolume: number = 0.8

  @input
  @hint("Mute all sound cues")
  muted: boolean = false
  @ui.group_end

  private players: {[key: string]: AudioComponent} = {}

  onAwake(): void {
    this.players.click = this.makePlayer("Click", SFX_CLICK)
    this.players.scan = this.makePlayer("Scan", SFX_SCAN)
    this.players.fault = this.makePlayer("Fault", SFX_FAULT)
    this.players.snap = this.makePlayer("Snap", SFX_SNAP)
    this.players.success = this.makePlayer("Success", SFX_SUCCESS)
    this.players.boot = this.makePlayer("Boot", SFX_BOOT)
    this.players.complete = this.makePlayer("Complete", SFX_COMPLETE)
  }

  playClick(): void { this.play("click") }
  playScan(): void { this.play("scan") }
  playFault(): void { this.play("fault") }
  playSnap(): void { this.play("snap") }
  playSuccess(): void { this.play("success") }
  playBoot(): void { this.play("boot") }
  playComplete(): void { this.play("complete") }

  private makePlayer(name: string, track: AudioTrackAsset): AudioComponent {
    const so = global.scene.createSceneObject("Sfx_" + name)
    so.setParent(this.sceneObject)
    const audio = so.createComponent("Component.AudioComponent") as AudioComponent
    audio.audioTrack = track
    audio.playbackMode = Audio.PlaybackMode.LowLatency // input-reactive cues
    return audio
  }

  private play(key: string): void {
    if (this.muted) return
    const a = this.players[key]
    if (!a || isNull(a)) return
    a.volume = this.sfxVolume
    if (a.isPlaying()) a.stop(false)
    a.play(1)
  }
}
